/* RP reference time is independent of the native chart and the transit search range. */
(function(root){'use strict';
function resolve(value,location,now=Date.now()){const state=value||{mode:'live'};if(state.mode==='live')return {mode:'live',instant:new Date(now),location:{...location}};if(state.mode!=='selected')throw Error('Choose Live or Selected date/time for RP.');const {date,time}=state,offset=Number(state.offset),normalized=/^\d{2}:\d{2}$/.test(time||'')?time+':00':time;if(!/^\d{4}-\d{2}-\d{2}$/.test(date||'')||!/^([01]\d|2[0-3]):[0-5]\d:[0-5]\d$/.test(normalized||'')||String(state.offset??'').trim()===''||!Number.isFinite(offset)||Math.abs(offset)>14)throw Error('Enter a valid RP date, time and UTC offset (−14 to +14).');const clock=Date.parse(date+'T'+normalized+'Z');if(!Number.isFinite(clock)||new Date(clock).toISOString().slice(0,19)!==date+'T'+normalized)throw Error('Enter a valid RP calendar date and time.');const instant=new Date(clock-offset*3600000);if(instant.getUTCFullYear()<1900||instant.getUTCFullYear()>2100)throw Error('RP dates must be within 1900–2100.');return {mode:'selected',instant,location:{...location,timezone:offset}};}
function shift(value,days){const normalized=String(value.date||''),date=new Date(normalized+'T00:00:00Z');if(!Number.isFinite(+date)||date.toISOString().slice(0,10)!==normalized)throw Error('Enter a valid RP date first.');date.setUTCDate(date.getUTCDate()+days);return {...value,mode:'selected',date:date.toISOString().slice(0,10)};}
root.KPRPReferenceTime={resolve,shift};
})(globalThis);
